const r = $input.first().json;
const out = String(r.stdout || '') + '\n' + String(r.stderr || '');
const code = Number(r.code ?? r.exitCode ?? 0);

// The SSH node reports the remote exit status but does NOT fail the workflow on a
// non-zero one. Without this check a failed dbt build looks exactly like a
// successful one: the schedule goes green, serving keeps yesterday's numbers, and
// nobody finds out until an analyst notices the data stopped moving.
const summary = (out.match(/Done\. PASS=\d+ WARN=\d+ ERROR=\d+ SKIP=\d+.*/) || [null])[0];
const m = summary ? summary.match(/PASS=(\d+) WARN=(\d+) ERROR=(\d+) SKIP=(\d+)/) : null;

if (code !== 0 || !m) {
  throw new Error(
    'dbt build FAILED (exit ' + code + '). Serving layer is stale — do not trust it ' +
    'until this is resolved.\n\n' + out.slice(-3000)
  );
}

const [, pass, warn, error, skip] = m.map(Number);

// A test that ERRORs or a model that is SKIPped means part of the graph did not
// build. dbt still exits 0 when tests merely warn, so exit code alone is not enough.
if (error > 0 || skip > 0) {
  throw new Error(
    'dbt build completed with ERROR=' + error + ' SKIP=' + skip + '. Part of the ' +
    'graph did not build.\n\n' + out.slice(-3000)
  );
}

return [{ json: { ok: true, pass, warn, error, skip, summary, built_at: new Date().toISOString() } }];

const r = $input.first().json;
const dbt = $('Assert dbt Succeeded').first().json;

// An empty serving view after a green build is the failure mode a row-count check
// exists to catch: every model "succeeded", but a broken upstream filter silently
// emptied the contract other teams read. Fail loudly rather than publish nothing.
if (Number(r.opportunities) === 0) {
  throw new Error('core.opportunities is EMPTY after a successful dbt build. The serving contract is broken.');
}

const syncedAt = r.opportunities_synced_at ? new Date(r.opportunities_synced_at) : null;
const ageHours = syncedAt ? (Date.now() - syncedAt.getTime()) / 3600000 : null;

// The published freshness target for SmartMoving dimensions is < 24 h.
if (ageHours !== null && ageHours > 26) {
  throw new Error(
    'core.opportunities.synced_at is ' + ageHours.toFixed(1) + ' h old, past the 24 h ' +
    'freshness target. dbt built fine, so the problem is upstream: extraction is not running.'
  );
}

return [{ json: {
  ok: true,
  dbt_pass: dbt.pass, dbt_warn: dbt.warn,
  opportunities: Number(r.opportunities),
  jobs_upcoming: Number(r.jobs_upcoming),
  leads_today: Number(r.leads_today),
  synced_age_hours: ageHours === null ? null : Number(ageHours.toFixed(2)),
} }];
